#include <iostream>
#include <numeric>
#include <vector>
int main() {
    std::vector<int> values; values.reserve(10000);
    for (int i = 0; i < 10000; ++i) values.push_back(i);
    const long long sum = std::accumulate(values.begin(), values.end(), 0LL);
    std::cout << "count=" << values.size() << ", sum=" << sum << '\n';
}
